// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20-like token that will accept transferFrom
        address token = address(new SimpleToken());

        // Create a fake 'from' address and fund it with tokens
        address from = address(0x123);

        // Grant approval: the from address approves C to transfer tokens
        vm.prank(from);
        SimpleToken(token).approve(address(c), 100);

        // Call transfer with the from address, the token, and one recipient
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint v = 10;

        bool result = c.transfer(from, token, tos, v);

        // The reference returns true; the buggy returns false
        assertTrue(result);
    }
}

contract SimpleToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor() {
        balanceOf[msg.sender] = 1000000;
    }

    function approve(address spender, uint256 amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        require(balanceOf[from] >= amount);
        require(allowance[from][msg.sender] >= amount);
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;
        return true;
    }
}

